      "proposed_laureates": [
        "Alexander Polyakov",
        "Edward Witten",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality created a profound link between quantum field theories and gravitational theories, with major influence across high-energy theory and condensed matter physics.",
        "attribution": "Polyakov helped establish key antecedents, Witten developed central connections, and Maldacena gave the explicit duality that transformed the subject; each role is distinct but part of a longer lineage.",
        "maturity": "The duality has been studied intensively for decades and is a durable organizing idea, although its most direct physical realization remains uncertain.",
        "uncertainties": [
          "The Nobel case for a primarily theoretical duality without direct empirical confirmation is less settled.",
          "The long intellectual lineage makes the choice of credited contributors especially consequential."
        ]
      }
    },
